from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row if x != 0)
    background = counts.most_common(1)[0][0]
    colors = [x for x in counts if x != background]
    if not colors:
        return [row[:] for row in grid]
    color = min(colors, key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    rmin, cmin = min(r for r, c in points), min(c for r, c in points)
    shape = [(r-rmin, c-cmin) for r, c in points]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r0 in range(h-sh+1):
        for c0 in range(w-sw+1):
            if all(grid[r0+r][c0+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[r0+r][c0+c] = color
    return out
